package com.example.auth;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController{private final JdbcTemplate jdbc; public AuthController(JdbcTemplate jdbc){this.jdbc=jdbc;} @PostMapping("/login") public Map<String,Object> login(@RequestBody Map<String,String> b){var rows=jdbc.queryForList("select id,nickname from user where username=? and password=?",b.get("username"),b.get("password")); return rows.isEmpty()?Map.of("success",false):Map.of("success",true,"data",rows.get(0));} @GetMapping("/users/{id}") public Map<String,Object> user(@PathVariable Long id){return jdbc.queryForMap("select id,username,nickname,email,phone from user where id=?",id);}}